#include <iostream>
#include <vector>
#include <cstddef>
#include <new>
#include <stdexcept>
#include <utility>

template <typename T, size_t BlockSize = 4096>
class MemoryPool {
private:
    union Slot {
        T element;
        Slot* next;
    };

    using Chunk = Slot[BlockSize];

    std::vector<Chunk*> chunks_;
    Slot* free_list_;

    void allocate_chunk() {
        Chunk* new_chunk = nullptr;
        try {
            new_chunk = new Chunk[1];
        } catch (const std::bad_alloc&) {
            throw;
        } 
        chunks_.push_back(new_chunk);

        for (size_t i = 0; i < BlockSize - 1; ++i) {
            new_chunk[i].next = &new_chunk[i + 1];
        }
        new_chunk[BlockSize - 1].next = free_list_;
        free_list_ = &new_chunk[0];
    }

public:
    MemoryPool() : free_list_(nullptr) {
        allocate_chunk();
    }

    ~MemoryPool() {
        for (Chunk* chunk : chunks_) {
            delete[] chunk;
        }
    }

    MemoryPool(const MemoryPool&) = delete;
    MemoryPool& operator=(const MemoryPool&) = delete;
    MemoryPool(MemoryPool&& other) noexcept 
        : chunks_(std::move(other.chunks_)), free_list_(other.free_list_) {
        other.free_list_ = nullptr;
    }

    MemoryPool& operator=(MemoryPool&& other) noexcept {
        if (this != &other) {
            for (Chunk* chunk : chunks_) {
                delete[] chunk;
            }
            chunks_ = std::move(other.chunks_);
            free_list_ = other.free_list_;
            other.free_list_ = nullptr;
        }
        return *this;
    }

    template <typename... Args>
    T* construct(Args&&... args) {
        if (free_list_ == nullptr) {
            allocate_chunk();
        }
        Slot* slot = free_list_;
        free_list_ = free_list_->next;

        try {
            T* ptr = ::new (static_cast<void*>(&slot->element)) T(std::forward<Args>(args)...);
            return ptr;
        } catch (...) {
            slot->next = free_list_;
            free_list_ = slot;
            throw;
        }
    }

    void destroy(T* ptr) {
        if (!ptr) return;
        ptr->~T();
        Slot* slot = reinterpret_cast<Slot*>(ptr);
        slot->next = free_list_;
        free_list_ = slot;
    }
};

