Here is the production-ready implementation of a lock-free Bounded SPSC Queue in modern C++. It uses `std::atomic` with memory acquire-release semantics to guarantee thread safety across multiple cores without the performance penalty of mutexes.

```cpp
#include <atomic>
#include <new>
#include <utility>
#include <stdexcept>
#include <iostream>
#include <cassert>

template <typename T, size_t Capacity>
class SPSCRingBuffer {
private:
    static_assert(Capacity > 0, "Capacity must be greater than zero");

    // Align to cache line size to prevent false sharing
    struct alignas(64) Cell {
        std::atomic<bool> initialized{false};
        typename std::aligned_storage<sizeof(T), alignof(T)>::type storage;
    };

    Cell buffer_[Capacity];

    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};

public:
    SPSCRingBuffer() = default;

    ~SPSCRingBuffer() {
        T dummy;
        while (pop(dummy)) {
            // Drain remaining elements to invoke destructors
        }
    }

    SPSCRingBuffer(const SPSCRingBuffer&) = delete;
    SPSCRingBuffer& operator=(const SPSCRingBuffer&) = delete;

    template <typename... Args>
    bool emplace(Args&&... args) {
        const size_t current_tail = tail_.load(std::memory_order_relaxed);
        const size_t current_head = head_.load(std::memory_order_acquire);

        if ((current_tail + 1) % Capacity == current_head) {
            return false; // Buffer is full
        }

        // Construct object in-place using placement new
        ::new (static_cast<void*>(&buffer_[current_tail].storage)) T(std::forward<Args>(args)...);

        buffer_[current_tail].initialized.store(true, std::memory_order_release);
        tail_.store((current_tail + 1) % Capacity, std::memory_order_release);
        return true;
    }

    bool push(const T& value) {
        return emplace(value);
    }

    bool push(T&& value) {
        return emplace(std::move(value));
    }

    bool pop(T& value) {
        const size_t current_head = head_.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Buffer is empty
        }

        // Wait until producer has marked the cell as initialized
        while (!buffer_[current_head].initialized.load(std::memory_order_acquire)) {
            // Spin-wait for visibility
        }

        T* ptr = reinterpret_cast<T*>(&buffer_[current_head].storage);
        value = std::move(*ptr);
        ptr->~T();

        buffer_[current_head].initialized.store(false, std::memory_order_release);
        head_.store((current_head + 1) % Capacity, std::memory_order_release);
        return true;
    }

    bool empty() const {
        return head_.load(std::memory_order_acquire) == tail_.load(std::memory_order_acquire);
    }
};

int main() {
    SPSCRingBuffer<int, 8> queue;

    assert(queue.empty() == true);

    // Test basic push/pop
    bool pushed = queue.push(42);
    assert(pushed == true);
    assert(queue.empty() == false);

    int val = 0;
    bool popped = queue.pop(val);
    assert(popped == true);
    assert(val == 42);
    assert(queue.empty() == true);

    // Test capacity limits
    for (int i = 0; i < 7; ++i) {
        assert(queue.push(i) == true);
    }
    // Buffer of size 8 holds at most 7 elements due to ring design
    assert(queue.push(99) == false);

    for (int i = 0; i < 7; ++i) {
        assert(queue.pop(val) == true);
        assert(val == i);
    }
    assert(queue.empty() == true);

    std::cout << "All SPSC Ring Buffer unit tests passed successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** O(1) constant time for both `push` and `pop` operations, as they directly index the ring buffer and perform atomic modifications without traversal or locking.
- **Space Complexity:** O(Capacity) space complexity, allocating a fixed-size array of `Capacity` cells aligned to cache boundaries to eliminate false sharing.

Here is a robust, production-grade fixed-size Memory Pool Allocator implemented in C99. It features intrusive free-list tracking, safety alignment constraints, and boundary validation to catch common memory corruptions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <assert.h>

#define MEMPOOL_MAGIC 0x5EEDCAFE

typedef struct MemBlockHeader {
    uint32_t magic;
    struct MemBlockHeader* next;
} MemBlockHeader;

typedef struct {
    uint8_t* memory_pool;
    MemBlockHeader* free_list;
    size_t block_size;
    size_t total_blocks;
    size_t free_blocks;
} MemoryPool;

MemoryPool* mempool_create(size_t block_size, size_t block_count) {
    if (block_size < sizeof(MemBlockHeader)) {
        block_size = sizeof(MemBlockHeader);
    }

    // Ensure proper alignment (8-byte alignment)
    size_t alignment = 8;
    if (block_size % alignment != 0) {
        block_size = ((block_size + alignment - 1) / alignment) * alignment;
    }

    size_t pool_bytes = block_size * block_count;
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL;
    }

    pool->memory_pool = (uint8_t*)malloc(pool_bytes);
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->total_blocks = block_count;
    pool->free_blocks = block_count;
    pool->free_list = NULL;

    // Link free list blocks intrusively
    for (size_t i = 0; i < block_count; ++i) {
        uint8_t* block_addr = pool->memory_pool + (i * block_size);
        MemBlockHeader* header = (MemBlockHeader*)block_addr;
        header->magic = MEMPOOL_MAGIC;
        header->next = pool->free_list;
        pool->free_list = header;
    }

    return pool;
}

void* mempool_alloc(MemoryPool* pool) {
    if (!pool || pool->free_blocks == 0 || !pool->free_list) {
        return NULL;
    }

    MemBlockHeader* header = pool->free_list;
    pool->free_list = header->next;
    pool->free_blocks--;

    // Clear the next pointer portion before returning user payload space
    uint8_t* user_payload = (uint8_t*)header + sizeof(MemBlockHeader);
    return (void*)user_payload;
}

bool mempool_free(MemoryPool* pool, void* ptr) {
    if (!pool || !ptr) {
        return false;
    }

    uint8_t* byte_ptr = (uint8_t*)ptr;
    uint8_t* header_addr = byte_ptr - sizeof(MemBlockHeader);

    // Validate bounds
    if (header_addr < pool->memory_pool || 
        header_addr >= pool->memory_pool + (pool->block_size * pool->total_blocks)) {
        return false;
    }

    MemBlockHeader* header = (MemBlockHeader*)header_addr;

    // Validate magic marker to catch corruption or double-free
    if (header->magic != MEMPOOL_MAGIC) {
        return false;
    }

    // Check if block is already marked free (Double Free Detection)
    MemBlockHeader* current = pool->free_list;
    while (current != NULL) {
        if (current == header) {
            return false; // Double free detected
        }
        current = current->next;
    }

    header->next = pool->free_list;
    pool->free_list = header;
    pool->free_blocks++;

    return true;
}

void mempool_destroy(MemoryPool* pool) {
    if (pool) {
        free(pool->memory_pool);
        free(pool);
    }
}

int main() {
    const size_t block_size = 32;
    const size_t block_count = 4;

    MemoryPool* pool = mempool_create(block_size, block_count);
    assert(pool != NULL);

    void* p1 = mempool_alloc(pool);
    void* p2 = mempool_alloc(pool);
    assert(p1 != NULL);
    assert(p2 != NULL);

    // Write data safely within bounds
    strcpy((char*)p1, "Hello Pool");
    printf("Allocated p1 data: %s\n", (char*)p1);

    // Free p1 and test reuse
    assert(mempool_free(pool, p1) == true);

    // Test double-free rejection
    assert(mempool_free(pool, p1) == false);

    // Allocate again, should reclaim p1 block
    void* p3 = mempool_alloc(pool);
    assert(p3 == p1);

    assert(mempool_free(pool, p2) == true);
    assert(mempool_free(pool, p3) == true);

    mempool_destroy(pool);
    printf(
        "All Memory Pool Allocator tests executed successfully.\n");
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** O(1) constant time for both allocation (`mempool_alloc`) and deallocation (`mempool_free`), as free list pointer updates happen strictly at the head of the list. (Note: Double-free detection walks the free list which takes O(K) where K is the number of free blocks, serving as a debug invariant safeguard).
- **Space Complexity:** O(N * M) where N is the number of blocks and M is the block size, plus a small O(1) fixed-size header overhead per block for intrusive pointers and magic boundary verification.

Here is the complete, production-grade implementation of a lock-free SPSC circular queue in C++20.

```cpp
#include <atomic>
#include <vector>
#include <optional>
#include <thread>
#include <iostream>
#include <cassert>

template <typename T, size_t Capacity>
class SPSCQueue {
private:
    static_assert(Capacity > 0, "Capacity must be greater than zero");
    // Pad to prevent false sharing on cache lines (typically 64 bytes)
    struct CachePad {
        alignas(64) std::atomic<size_t> value{0};
    };

    std::vector<T> buffer_;
    CachePad head_;
    CachePad tail_;

public:
    SPSCQueue() : buffer_(Capacity) {}

    bool push(const T& item) {
        const size_t current_tail = tail_.value.load(std::memory_order_relaxed);
        const size_t current_head = head_.value.load(std::memory_order_acquire);

        if ((current_tail - current_head) >= Capacity) {
            return false; // Queue is full
        }

        buffer_[current_tail % Capacity] = item;
        tail_.value.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    bool push(T&& item) {
        const size_t current_tail = tail_.value.load(std::memory_order_relaxed);
        const size_t current_head = head_.value.load(std::memory_order_acquire);

        if ((current_tail - current_head) >= Capacity) {
            return false; // Queue is full
        }

        buffer_[current_tail % Capacity] = std::move(item);
        tail_.value.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    std::optional<T> pop() {
        const size_t current_head = head_.value.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.value.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return std::nullopt; // Queue is empty
        }

        T item = std::move(buffer_[current_head % Capacity]);
        head_.value.store(current_head + 1, std::memory_order_release);
        return item;
    }

    [[nodiscard]] size_t size() const {
        size_t head = head_.value.load(std::memory_order_acquire);
        size_t tail = tail_.value.load(std::memory_order_acquire);
        return (tail >= head) ? (tail - head) : 0;
    }
};

int main() {
    SPSCQueue<int, 1024> queue;
    constexpr int total_items = 10000;

    std::thread producer([&]() {
        for (int i = 0; i < total_items; ++i) {
            while (!queue.push(i)) {
                std::this_thread::yield();
            }
        }
    });

    std::thread consumer([&]() {
        int consumed = 0;
        while (consumed < total_items) {
            if (auto item = queue.pop(); item.has_value()) {
                assert(*item == consumed);
                consumed++;
            } else {
                std::this_thread::yield();
            }
        }
        std::cout << "Successfully consumed " << consumed << " items without data loss.\n";
    });

    producer.join();
    consumer.join();
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - `push()`: $O(1)$ constant time.
  - `pop()`: $O(1)$ constant time.
  - `size()`: $O(1)$ constant time.
- **Space Complexity**: $O(C)$ where $C$ is the fixed `Capacity` of the queue buffer, with explicit cache-line alignment (`alignas(64)`) to mitigate false sharing between CPU cores.

### Error Handling and Invariant Management
1. **Capacity Boundaries**: Enforced via compile-time `static_assert` and checked dynamically using atomic difference calculations to prevent buffer overflows.
2. **Memory Ordering**: Uses `std::memory_order_acquire` and `std::memory_order_release` to establish a happens-before relationship between the producer and consumer threads without heavy mutex overhead.
3. **False Sharing Mitigation**: Encapsulates atomic indices in padded structures (`CachePad`) ensuring separate cache lines for head and tail pointers.

Here is the complete, robust implementation of a thread-safe bounded blocking queue in Python.

```python
from collections import deque
import threading
from typing import Generic, TypeVar

T = TypeVar('T')

class BoundedBlockingQueue(Generic[T]):
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("Capacity must be a positive integer greater than zero.")

        self._capacity = capacity
        self._queue: deque[T] = deque()
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)
        self._is_closed = False

    def put(self, item: T, timeout: float | None = None) -> None:
        with self._not_full:
            if self._is_closed:
                raise RuntimeError("Cannot put item into a closed queue.")

            if timeout is not None and timeout < 0:
                raise ValueError("Timeout cannot be negative.")

            if timeout is None:
                while len(self._queue) >= self._capacity:
                    if self._is_closed:
                        raise RuntimeError("Queue was closed while waiting.")
                    self._not_full.wait()
            else:
                import time
                endtime = time.monotonic() + timeout
                while len(self._queue) >= self._capacity:
                    if self._is_closed:
                        raise RuntimeError("Queue was closed while waiting.")
                    remaining = endtime - time.monotonic()
                    if remaining <= 0.0:
                        raise TimeoutError("Timed out waiting to put item into queue.")
                    self._not_full.wait(timeout=remaining)

            self._queue.append(item)
            self._not_empty.notify()

    def get(self, timeout: float | None = None) -> T:
        with self._not_empty:
            if timeout is not None and timeout < 0:
                raise ValueError("Timeout cannot be negative.")

            if timeout is None:
                while not self._queue:
                    if self._is_closed:
                        raise RuntimeError("Cannot get item from an empty closed queue.")
                    self._not_empty.wait()
            else:
                import time
                endtime = time.monotonic() + timeout
                while not self._queue:
                    if self._is_closed:
                        raise RuntimeError("Cannot get item from an empty closed queue.")
                    remaining = endtime - time.monotonic()
                    if remaining <= 0.0:
                        raise TimeoutError("Timed out waiting to get item from queue.")
                    self._not_empty.wait(timeout=remaining)

            item = self._queue.popleft()
            self._not_full.notify()
            return item

    def close(self) -> None:
        with self._lock:
            self._is_closed = True
            self._not_full.notify_all()
            self._not_empty.notify_all()

    def __len__(self) -> int:
        with self._lock:
            return len(self._queue)

if __name__ == "__main__":
    import time

    q = BoundedBlockingQueue[int](capacity=2)

    def worker_producer():
        try:
            for i in range(5):
                q.put(i)
                print(f"Produced: {i}")
            q.close()
        except Exception as e:
            print(f"Producer error: {e}")

    def worker_consumer():
        try:
            while True:
                item = q.get(timeout=1.0)
                print(f"Consumed: {item}")
                time.sleep(0.2)
        except TimeoutError:
            print("Consumer timed out waiting for items.")
        except RuntimeError as e:
            print(f"Consumer terminated cleanly: {e}")

    t1 = threading.Thread(target=worker_producer)
    t2 = threading.Thread(target=worker_consumer)

    t1.start()
    t2.start()

    t1.join()
    t2.join()
```

### Complexity Analysis
- **Time Complexity**:
  - `put()`: $O(1)$ amortized (queue operations are $O(1)$, wait loops scale with contention).
  - `get()`: $O(1)$ constant time.
  - `close()`: $O(1)$ constant time.
- **Space Complexity**: $O(C)$ where $C$ is the maximum capacity bound enforced on the internal `deque`.

### Error Handling and Invariant Management
1. **Spurious Wakeup Protection**: Explicit `while` condition loops surround every `wait()` call to verify that predicates (`len(self._queue) < self._capacity` or `bool(self._queue)`) remain valid upon waking.
2. **State Protection**: Validates queue closed states and negative timeouts gracefully, raising `RuntimeError` and `ValueError` respectively.
3. **Thread Safety**: Uses condition variables backed by a single reentrant-safe mutual exclusion lock (`threading.Lock`) to prevent race conditions during state transitions.

Here is the production-ready SPSC lock-free queue implemented in C++20 using atomic memory ordering semantics.

```cpp
#include <atomic>
#include <vector>
#include <optional>
#include <iostream>
#include <thread>
#include <cassert>

template <typename T, size_t Capacity>
class SPSCQueue {
private:
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");

    struct Node {
        T data;
    };

    // Pad to prevent false sharing on cache lines (typically 64 bytes)
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
    alignas(64) Node* buffer_;
    const size_t mask_;

public:
    SPSCQueue() : mask_(Capacity - 1) {
        buffer_ = static_cast<Node*>(::operator new[](Capacity * sizeof(Node)));
    }

    ~SPSCQueue() {
        // Drain remaining elements
        T dummy;
        while (dequeue(dummy));
        ::operator delete[](buffer_);
    }

    SPSCQueue(const SPSCQueue&) = delete;
    SPSCQueue& operator=(const SPSCQueue&) = delete;

    bool enqueue(const T& item) {
        const size_t current_tail = tail_.load(std::memory_order_relaxed);
        const size_t current_head = head_.load(std::memory_order_acquire);

        if ((current_tail - current_head) == Capacity) {
            return false; // Queue is full
        }

        new (&buffer_[current_tail & mask_].data) T(item);
        tail_.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    bool dequeue(T& item) {
        const size_t current_head = head_.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Queue is empty
        }

        item = std::move(buffer_[current_head & mask_].data);
        buffer_[current_head & mask_].data.~T();
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }
};

int main() {
    SPSCQueue<int, 1024> queue;
    std::atomic<bool> finished{false};

    std::thread producer([&]() {
        for (int i = 0; i < 5000; ++i) {
            while (!queue.enqueue(i)) {
