- **Time Complexity:** $\mathcal{O}(1)$ amortized per operation.
- **Space Complexity:** $\mathcal{O}(Capacity)$ fixed memory allocation.

Here is a complete, thread-safe worker pool thread coordinator implemented from scratch in Python.

```python
import threading
import queue
import time
from typing import Callable, Any

class SimpleThreadPool:
    def __init__(self, num_threads: int):
        self._tasks: queue.Queue[Callable[[], Any] | None] = queue.Queue()
        self._workers: list[threading.Thread] = []
        self._shutdown = False

        for _ in range(num_threads):
            t = threading.Thread(target=self._worker_loop)
            t.daemon = True
            t.start()
            self._workers.append(t)

    def _worker_loop(self) -> None:
        while not self._shutdown:
            try:
                task = self._tasks.get(timeout=0.1)
            except queue.Empty:
                continue

            if task is None:
                break

            try:
                task()
            except Exception as e:
                print(f"Task failed with exception: {e}")
            finally:
                self._tasks.task_done()

    def submit(self, func: Callable[[], Any]) -> None:
        if self._shutdown:
            raise RuntimeError("ThreadPool is shut down")
        self._tasks.put(func)

    def shutdown(self) -> None:
        self._shutdown = True
        for _ in self._workers:
            self._tasks.put(None)
        for t in self._workers:
            t.join()

if __name__ == "__main__":
    pool = SimpleThreadPool(2)
    results = []

    def sample_task():
        results.append(42)

    pool.submit(sample_task)
    time.sleep(0.2)
    pool.shutdown()
    assert results == [42]
    print("ThreadPool test passed successfully.")
```

