Here is the complete implementation of a thread-safe bounded blocking queue in Python using condition variables.

```python
import threading
import time
from typing import TypeVar, Generic, Optional

T = TypeVar('T')

class ShutdownException(Exception):
    pass

class BoundedBlockingQueue(Generic[T]):
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self._capacity = capacity
        self._queue: list[T] = []
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)
        self._is_shutdown = False

    def put(self, item: T, timeout: Optional[float] = None) -> None:
        endtime = None if timeout is None else time.time() + timeout
        with self._not_full:
            while len(self._queue) >= self._capacity:
                if self._is_shutdown:
                    raise ShutdownException("Queue is shut down")
                if timeout is not None:
                    remaining = endtime - time.time()
                    if remaining <= 0:
                        raise TimeoutError("Put operation timed out")
                    self._not_full.wait(timeout=remaining)
                else:
                    self._not_full.wait()

                if self._is_shutdown:
                    raise ShutdownException("Queue is shut down")

            self._queue.append(item)
            self._not_empty.notify()

    def get(self, timeout: Optional[float] = None) -> T:
        endtime = None if timeout is None else time.time() + timeout
        with self._not_empty:
            while not self._queue:
                if self._is_shutdown:
                    raise ShutdownException(
                        "Queue is shut down and empty"
                    ) if not self._queue else self._queue.pop(0)
                if timeout is not None:
                    remaining = endtime - time.time()
                    if remaining <= 0:
                        raise TimeoutError("Get operation timed out")
                    self._not_empty.wait(timeout=remaining)
                else:
                    self._not_empty.wait()

                if not self._queue and self._is_shutdown:
                    raise ShutdownException("Queue is shut down and empty")

            item = self._queue.pop(0)
            self._not_full.notify()
            return item

    def shutdown(self) -> None:
        with self._lock:
            self._is_shutdown = True
            self._not_full.notify_all()
            self._not_empty.notify_all()

if __name__ == "__main__":
    q = BoundedBlockingQueue[int](2)

    def producer():
        try:
            for i in range(5):
                q.put(i)
                print(f"Produced: {i}")
        except ShutdownException:
            print("Producer shut down")

    def consumer():
        try:
            while True:
                item = q.get(timeout=1.0)
                print(f"Consumed: {item}")
        except (ShutdownException, TimeoutError):
            print("Consumer terminated")

    t1 = threading.Thread(target=producer)
    t2 = threading.Thread(target=consumer)

    t1.start()
    t2.start()

    t1.join()
    time.sleep(0.5)
    q.shutdown()
    t2.join()
```

