- Ensures assertion checks on inputs.
- Prevents writer starvation via tracking `writers_waiting` counters.

Here is the complete implementation of a lock-free Treiber Stack in C++20.

```cpp
#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

template <typename T>
class TreiberStack {
private:
    struct Node {
        T data;
        Node* next;
        explicit Node(const T& val) : data(val), next(nullptr) {}
    };

    std::atomic<Node*> head;

public:
    TreiberStack() : head(nullptr) {}

    ~TreiberStack() {
        T dummy;
        while (pop(dummy));
    }

    void push(const T& val) {
        Node* new_node = new Node(val);
        new_node->next = head.load(std::memory_order_relaxed);

        while (!head.compare_exchange_weak(
            new_node->next,
            new_node,
            std::memory_order_release,
            std::memory_order_relaxed
        )) {
            // CAS failed, new_node->next was updated by compare_exchange_weak
        }
    }

    bool pop(T& result) {
        Node* old_head = head.load(std::memory_order_acquire);

        while (old_head && !head.compare_exchange_weak(
            old_head,
            old_head->next,
            std::memory_order_acquire,
            std::memory_order_relaxed
        )) {
            // CAS failed, old_head was updated
        }

        if (old_head == nullptr) {
            return false;
        }

        result = old_head->data;
        delete old_head;
        return true;
    }
};

int main() {
    TreiberStack<int> stack;
    stack.push(10);
    stack.push(20);

    int val;
    if (stack.pop(val)) std::cout << "Popped: " << val << std::endl;
    if (stack.pop(val)) std::cout << "Popped: " << val << std::endl;

    return 0;
}
```

