- Clean destruction guarantees no memory leaks upon termination.

Here is the complete implementation of a lock-free Single Producer Single Consumer (SPSC) ring buffer in C++20.

```cpp
#include <atomic>
#include <vector>
#include <iostream>
#include <thread>

template <typename T, size_t Capacity>
class SPSCRingBuffer {
private:
    // Align to cache line size to prevent false sharing
    alignas(64) std::atomic<size_t> head;
    alignas(64) std::atomic<size_t> tail;
    std::vector<T> buffer;

public:
    SPSCRingBuffer() : head(0), tail(0), buffer(Capacity + 1) {}

    bool push(const T& item) {
        const size_t current_head = head.load(std::memory_order_relaxed);
        const size_t current_tail = tail.load(std::memory_order_acquire);

        if ((current_head + 1) % buffer.size() == current_tail) {
            return false; // Full
        }

        buffer[current_head] = item;
        head.store((current_head + 1) % buffer.size(), std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const size_t current_tail = tail.load(std::memory_order_relaxed);
        const size_t current_head = head.load(std::memory_order_acquire);

        if (current_tail == current_head) {
            return false; // Empty
        }

        item = buffer[current_tail];
        tail.store((current_tail + 1) % buffer.size(), std::memory_order_release);
        return true;
    }
};

int main() {
    SPSCRingBuffer<int, 1024> rb;
    std::thread producer([&]() {
        for (int i = 0; i < 100; ++i) {
            while (!rb.push(i));
        }
    });

    std::thread consumer([&]() {
        int val;
        int count = 0;
        while (count < 100) {
            if (rb.pop(val)) {
                count++;
            }
        }
        std::cout << "Consumed 100 items successfully.\n";
    });

    producer.join();
    consumer.join();
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** $O(1)$ constant time push and pop operations.
- **Space Complexity:** $O(C)$ where $C$ is the capacity of the buffer.

### Error Handling and Invariant Management
- Eliminates locking overhead by relying strictly on atomic indices and acquire-release semantics.

