```python
import threading
import queue
from typing import Callable, Any

class ThreadPool:
    def __init__(self, num_threads: int):
        self._tasks: queue.Queue[tuple[Callable[..., Any], tuple, dict]] = queue.Queue()
        self._workers = []
        self._shutdown = False
        self._lock = threading.Lock()

        for _ in range(num_threads):
            t = threading.Thread(target=self._worker_loop)
            t.daemon = True
            t.start()
            self._workers.append(t)

    def _worker_loop(self) -> None:
        while True:
            try:
                task, args, kwargs = self._tasks.get(timeout=0.1)
            except queue.Empty:
                with self._lock:
                    if self._shutdown:
                        break
                continue

            try:
                task(*args, **kwargs)
            except Exception as e:
                print(f"Task execution failed: {e}")
            finally:
                self._tasks.task_done()

    def submit(self, func: Callable[..., Any], *args: Any, **kwargs: Any) -> None:
        with self._lock:
            if self._shutdown:
                raise RuntimeError("Cannot schedule new tasks after shutdown")
        self._tasks.put((func, args, kwargs))

    def shutdown(self, wait: bool = True) -> None:
        with self._lock:
            self._shutdown = True

        if wait:
            self._tasks.join()

if __name__ == "__main__":
    pool = ThreadPool(num_threads=2)
    pool.submit(print, "Hello from thread pool")
    pool.shutdown(wait=True)
```

### Complexity Analysis
- **Time Complexity:** $O(1)$ task submission time.
- **Space Complexity:** $O(T)$ where $T$ is the number of queued tasks.

Here is the complete C++20 counting semaphore implementation.

```cpp
#include <mutex>
#include <condition_variable>
#include <chrono>

class Semaphore {
private:
    std::mutex mtx;
    std::condition_variable cv;
    int count;

public:
    explicit Semaphore(int initial_count = 0) : count(initial_count) {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return count > 0; });
        count--;
    }

    template <typename Rep, typename Period>
    bool try_acquire_for(const std::chrono::duration<Rep, Period>& rel_time) {
        std::unique_lock<std::mutex> lock(mtx);
        if (!cv.wait_for(lock, rel_time, [this]() { return count > 0; })) {
            return false;
        }
        count--;
        return true;
    }

    void release() {
        std::lock_guard<std::mutex> lock(mtx);
        count++;
        cv.notify_one();
    }
};

int main() {
    Semaphore sem(1);
    sem.acquire();
    sem.release();
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** $O(1)$ acquisition and release time.
- **Space Complexity:** $O(1)$ memory footprint.

