Here is the complete CountDownLatch implementation in Python.

```python
import threading

class CountDownLatch:
    def __init__(self, count: int):
        if count < 0:
            raise ValueError("Count cannot be negative")
        self._count = count
        self._lock = threading.Lock()
        self._cond = threading.Condition(self._lock)

    def countdown(self) -> None:
        with self._lock:
            if self._count > 0:
                self._count -= 1
                if self._count == 0:
                    self._cond.notify_all()

    def wait(self) -> None:
        with self._lock:
            while self._count > 0:
                self._cond.wait()

if __name__ == "__main__":
    latch = CountDownLatch(2)
    latch.countdown()
    latch.countdown()
    latch.wait()
```

